from datetime import datetime, timedelta
from functools import partial
from funcy import cache, memoize, SkipMemoization, reraise

calls = []
@cache(60, key_func=lambda x: x)
def cached(x):
    calls.append(x)
    if x < 0:
        raise cached.skip('uncached')
    return x * 2
assert cached.skip is SkipMemoization is memoize.skip
assert cached.memory == {}
assert cached(2) == cached(2) == 4
assert calls == [2]
assert cached.memory[2][0] == 4
cached.memory[2] = (10, datetime.now())
assert cached(2) == 10
cached.memory[2] = (10, datetime.now() - timedelta(seconds=61))
assert cached(2) == 4
cached.memory.clear()
assert cached(2) == 4
assert cached(-1) == cached(-1) == 'uncached'
assert -1 not in cached.memory
cached.invalidate(2)
assert 2 not in cached.memory
cached(3)
cached.invalidate_all()
assert cached.memory == {}

original = ValueError('original')
seen = []
def transform(error):
    seen.append(error)
    return RuntimeError('transformed: ' + str(error))
for into in (RuntimeError, RuntimeError('instance'), transform,
             partial(lambda prefix, error: RuntimeError(prefix + str(error)), 'partial: ')):
    try:
        with reraise(ValueError, into):
            raise original
    except RuntimeError as error:
        assert error.__cause__ is original
        if isinstance(into, BaseException):
            assert error is into
    else:
        raise AssertionError('not raised')
assert seen == [original]

@reraise(ValueError, transform)
def decorated(error=None):
    if error is not None:
        raise error
    return 42
assert decorated() == 42
for _ in range(2):
    try:
        decorated(original)
    except RuntimeError as error:
        assert error.__cause__ is original
assert seen == [original] * 3
try:
    decorated(TypeError('not matched'))
except TypeError:
    pass
assert seen == [original] * 3

class CallableError(RuntimeError):
    def __call__(self, error):
        raise AssertionError('exception instances must not be called')
instance = CallableError('instance')
try:
    with reraise(ValueError, instance):
        raise original
except CallableError as error:
    assert error is instance
    assert error.__cause__ is original
print('Targeted cache and reraise checks passed')
